def compute(vars):
    december_shares = vars["v1"]
    quarter_shares = vars["v2"]
    if quarter_shares == 0:
        return None

    share_ratio = december_shares / quarter_shares
    percentage = share_ratio * 100

    return {
        "value": percentage,
        "trace": {
            "december_shares": december_shares,
            "quarter_shares": quarter_shares,
            "share_ratio": share_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
